#!/usr/bin/env python3
"""Create focused Portuguese service pages from the authoritative treatment directory."""
from __future__ import annotations
import json, re, unicodedata
from html import escape
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
SOURCE = (ROOT / "tratamentos.html").read_text(encoding="utf-8")
ASSETS = ROOT / "data" / "service-image-sources.json"
OUT = ROOT / "servicos"; OUT.mkdir(exist_ok=True)

def slugify(value: str) -> str:
    value = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9]+", "-", value).strip("-").replace("--", "-")

pattern = re.compile(r'title:\s*"(?P<title>[^"]+)"\s*,\s*image:\s*"[^"]+"\s*,\s*alt:\s*"[^"]+"\s*,\s*summary:\s*"(?P<summary>[^"]+)".*?technology:\s*"(?P<technology>[^"]+)".*?important:\s*"(?P<important>[^"]+)"', re.S)
treatments = [m.groupdict() for m in pattern.finditer(SOURCE)]
if len(treatments) < 20: raise RuntimeError(f"Expected 20+ treatments, found {len(treatments)}")
images = json.loads(ASSETS.read_text(encoding="utf-8"))

def image_markup(slug: str, title: str, position: int, eager: bool = False) -> tuple[str, dict]:
    image_key = slug if slug in images else slug.replace("2", "")
    asset = images[image_key][position]
    path = ROOT / asset["file"]
    width, height = Image.open(path).size
    alt = f"Imagem editorial de atendimento e cuidado profissional para {title.lower()} em Londrina, imagem {position + 1}."
    tag = f'<img src="../{asset["file"]}" width="{width}" height="{height}" alt="{alt}" data-description="Imagem editorial licenciada para a página de {title} em Londrina; fotografia {position + 1}, distinta das demais imagens desta página." loading="{"eager" if eager else "lazy"}" {"fetchpriority=\"high\"" if eager else ""}>'
    return tag, {"url": f"https://www.francielesofiati.com/{asset['file']}", "width": width, "height": height, "caption": alt}

routes = []
for item in treatments:
    title, summary, technology, important = (item[key] for key in ("title", "summary", "technology", "important"))
    slug = slugify(title); routes.append(f"servicos/{slug}.html")
    if slug not in images and slug.replace("2", "") in images:
        images[slug] = images[slug.replace("2", "")]
    hero, schema_hero = image_markup(slug, title, 0, True)
    detail, schema_detail = image_markup(slug, title, 1)
    close, schema_close = image_markup(slug, title, 2)
    canonical = f"https://www.francielesofiati.com/servicos/{slug}"
    description = f"{title} em Londrina: entenda como Franciele Sofiati avalia indicação, preparo, recuperação e limites deste cuidado estético."
    image_schema = ",".join(json.dumps({"@type":"ImageObject", "@id": f"{image['url']}#primaryimage", "contentUrl": image["url"], "width": image["width"], "height": image["height"], "caption": image["caption"]}, ensure_ascii=False) for image in (schema_hero, schema_detail, schema_close))
    html = f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"><title>{escape(title)} em Londrina | Franciele Sofiati</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="pt-BR" href="{canonical}"><link rel="alternate" hreflang="x-default" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} em Londrina | Franciele Sofiati"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://www.francielesofiati.com/{images[slug][0]['file']}"><meta property="og:image:secure_url" content="https://www.francielesofiati.com/{images[slug][0]['file']}"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="{schema_hero['width']}"><meta property="og:image:height" content="{schema_hero['height']}"><meta property="og:image:alt" content="{schema_hero['caption']}"><meta property="og:site_name" content="Franciele Sofiati"><meta property="og:locale" content="pt_BR"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)} em Londrina | Franciele Sofiati"><meta name="twitter:description" content="{escape(description)}"><meta name="twitter:image" content="https://www.francielesofiati.com/{images[slug][0]['file']}"><meta name="twitter:image:alt" content="{schema_hero['caption']}"><link rel="stylesheet" href="../css/site.css"><script type="application/ld+json">{{"@context":"https://schema.org","@graph":[{{"@type":"WebSite","@id":"https://www.francielesofiati.com/#website","url":"https://www.francielesofiati.com/","name":"Franciele Sofiati"}},{{"@type":"Person","@id":"https://www.francielesofiati.com/#franciele","name":"Franciele Sofiati","identifier":{{"@type":"PropertyValue","propertyID":"CRBM","value":"6277"}}}},{{"@type":"HealthAndBeautyBusiness","@id":"https://www.francielesofiati.com/#practice","name":"Franciele Sofiati","url":"https://www.francielesofiati.com/","areaServed":{{"@type":"City","name":"Londrina","containedInPlace":{{"@type":"State","name":"Paraná","containedInPlace":{{"@type":"Country","name":"Brasil"}}}}}}}},{{"@type":"Service","@id":"{canonical}#service","url":"{canonical}","name":"{escape(title)}","description":"{escape(description)}","provider":{{"@id":"https://www.francielesofiati.com/#practice"}},"areaServed":{{"@type":"City","name":"Londrina"}}}},{{"@type":"WebPage","@id":"{canonical}#webpage","url":"{canonical}","name":"{escape(title)} em Londrina | Franciele Sofiati","inLanguage":"pt-BR","about":{{"@id":"{canonical}#service"}}}},{image_schema},{{"@type":"BreadcrumbList","@id":"{canonical}#breadcrumb","itemListElement":[{{"@type":"ListItem","position":1,"name":"Início","item":"https://www.francielesofiati.com/"}},{{"@type":"ListItem","position":2,"name":"Tratamentos","item":"https://www.francielesofiati.com/tratamentos"}},{{"@type":"ListItem","position":3,"name":"{escape(title)}","item":"{canonical}"}}]}}]}}</script></head><body class="sf-site sf-page sf-family-content sf-journal-article" data-page="journal" data-site-root="../"><a class="skip-link" href="#main-content">Pular para o conteúdo</a><template data-sf-partial="topbar"></template><template data-sf-partial="header"></template><template data-sf-partial="mobile-menu"></template><main class="sf-main sja-main" id="main"><nav class="sf-breadcrumbs sf-container" aria-label="Navegação estrutural"><ol><li><a href="../index.html">Início</a></li><li><a href="../tratamentos.html">Tratamentos</a></li><li><span aria-current="page">{escape(title)}</span></li></ol></nav><article class="sja-article"><header class="sja-hero sja-hero--portrait-led sf-container"><div class="sja-hero__intro"><p class="sja-publication">TRATAMENTO <span aria-hidden="true">/</span> LONDRINA · PARANÁ</p><h1>{escape(title)}</h1><p class="sja-standfirst">{escape(summary)}</p><div class="sja-byline"><span>Franciele Sofiati · CRBM 6277</span><span>Orientação e avaliação individual</span></div></div><figure class="sja-hero__feature">{hero}<figcaption>Atendimento em Londrina · imagem editorial licenciada</figcaption></figure></header><a class="skip-past-hero" href="#main-content">Continuar <span aria-hidden="true">↓</span></a><span class="sf-main-content-target" id="main-content" tabindex="-1"></span><div class="sja-reading-grid sf-container"><aside class="sja-at-glance"><div><p>Antes de decidir</p><h2>O que considerar</h2><ol><li>A indicação depende da avaliação presencial e da segurança no dia.</li><li>Preparo, parâmetros e recuperação são individualizados.</li><li>Resultados podem ser graduais, parciais e variáveis.</li></ol><a href="../consulta.html">Agendar consulta →</a></div></aside><div class="sja-prose"><section class="sja-reading-section"><h2>Como este tratamento é planejado</h2><p>{escape(technology)}</p><p>Na consulta, a queixa, o histórico, a condição atual da pele e os objetivos ajudam a definir se esta opção faz sentido, se é necessário preparar a região ou se outro caminho é mais adequado.</p></section><figure class="sja-inline-figure">{detail}<figcaption>Imagem editorial de cuidado profissional. Não representa resultado nem procedimento específico.</figcaption></figure><section class="sja-reading-section"><h2>Quando pode ser considerado</h2><p>{escape(important)}</p><p>A possibilidade de realizar o tratamento depende de fatores como integridade da pele, exposição solar, procedimentos recentes, medicamentos, alergias e condições relevantes informadas na avaliação.</p></section><section class="sja-reading-section"><h2>Recuperação e expectativas</h2><p>O tempo de recuperação, a necessidade de cuidados posteriores e a resposta variam conforme a técnica, a área e a pessoa. Nenhuma página consegue confirmar indicação, número de sessões ou resultado para um caso individual.</p><p>Sinais como dor intensa, secreção, piora progressiva, febre, bolhas extensas ou alteração importante de cor devem ser comunicados e podem exigir avaliação médica.</p></section><figure class="sja-inline-figure">{close}<figcaption>Uma consulta cuidadosa ajuda a transformar dúvidas em um próximo passo seguro.</figcaption></figure><section class="sja-reading-section"><h2>Atendimento em Londrina e região</h2><p>Franciele atende em Londrina. Pessoas de cidades próximas do Norte do Paraná podem buscar uma consulta quando desejarem uma avaliação presencial; a indicação continua individual e não depende de onde a pessoa mora.</p><p><a href="../consulta.html">Agendar uma consulta em Londrina →</a> · <a href="../tratamentos.html">Ver todos os tratamentos →</a></p></section></div></div></article></main><template data-sf-partial="newsletter-strip"></template><template data-sf-partial="footer"></template><template data-sf-partial="cookie-banner"></template><template data-sf-partial="floating-widgets"></template><script defer src="../js/analytics-config.js"></script><script defer src="../js/consent-manager.js"></script><script defer src="../js/analytics.js"></script><script type="module" src="../js/main.js"></script></body></html>'''
    (OUT / f"{slug}.html").write_text(html, encoding="utf-8")
(ROOT / "data" / "content-pages.json").write_text(json.dumps({"routes": routes}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
(ROOT / "data" / "all-treatment-slugs.json").write_text(json.dumps({"slugs": [slugify(item['title']) for item in treatments]}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
keep = {Path(route).name for route in routes}
for stale in OUT.glob("*.html"):
    if stale.name not in keep:
        stale.unlink()
